const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat ../research/skill-candidates/REVIEW.md
 cat ../research/mixed-gambles-design/evaluator/conventional-datalad-note.md
 cat ../research/mixed-gambles-design/evaluator/stage-01/review.md
 cat ../research/mixed-gambles-design/evaluator/stage-02/review.md
 cat ../research/mixed-gambles-design/evaluator/stage-03/review.md",max_output_tokens:15000}),
  tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
import json
root=Path('..').resolve()
for name in ['log-export-plan-02.json','log-export-report-02.json']:
    data=json.loads((root/'research/logs'/name).read_text())
    print(name)
    for key,value in data.items():
        if isinstance(value,list):
            selected=[x for x in value if isinstance(x,dict) and '/research/skill-drafts/logs/' in str(x.get('destination',''))]
            print(key, 'total',len(value),'selected',len(selected))
            for item in selected:
                print(json.dumps(item))
        else:
